93 |     /**
94 |      * combine APIs from the REST docs into one map, merging those APIs with matching identifiers
95 |      */
96 |     private Collection<RestDocumentation.RestApi> mergeApis(List<RestDocumentation> docs) {
97 |         Map<String,RestDocumentation.RestApi> aggregatedApis = new LinkedHashMap<String,RestDocumentation.RestApi>();
98 |         for (RestDocumentation doc : docs) {
99 |             for (RestDocumentation.RestApi api : doc.getApis()) {
100 |                 if (!aggregatedApis.containsKey(api.getIdentifier())) {
101 |                     aggregatedApis.put(api.getIdentifier(), api);
102 |                 }
103 |                 else {
104 |                     aggregatedApis.get(api.getIdentifier()).merge(api);
105 |                 }
106 |             }
107 |         }
108 |         return aggregatedApis.values();
109 |     }
