111 |     /**
112 |      * Filter out APIs based on user provided exclude patterns and selected scope (scope of 'all' implies no filtering).
113 |      */
114 |     private Collection<RestDocumentation.RestApi> filterApis(
115 |             Collection<RestDocumentation.RestApi> apis, Iterable<Pattern> excludePatterns, String scope) {
116 | 
117 |         // filter doc objects by client provided exclude patterns
118 |         Collection<RestDocumentation.RestApi> filteredApis = null;
119 |         if (excludePatterns != null) {
120 |             filteredApis = new LinkedList<RestDocumentation.RestApi>();
121 |             for (RestDocumentation.RestApi api : apis)
122 |                 filteredApis.add(api.filter(excludePatterns));
123 |         } else {
124 |             filteredApis = apis;
125 |         }
126 | 
127 |         // use command-line --scope value to filter the generated documentation
128 |         if (!scope.equals("all")) {
129 |             HashSet<String> requestedScopes = new HashSet<String>(Arrays.asList(new String[]{scope}));
130 | 
131 |             // ugly old-style iterating because we need to be able to remove elements as we go
132 |             Iterator<RestDocumentation.RestApi> apiIter = filteredApis.iterator();
133 |             while (apiIter.hasNext()) {
134 |                 RestDocumentation.RestApi api = apiIter.next();
135 |                 Iterator<RestDocumentation.RestApi.Resource> resIter = api.getResources().iterator();
136 |                 while (resIter.hasNext()) {
137 |                     RestDocumentation.RestApi.Resource resource = resIter.next();
138 |                     Iterator<RestDocumentation.RestApi.Resource.Method> methIter = resource.getRequestMethodDocs().iterator();
139 |                     while (methIter.hasNext()) {
140 |                         HashSet<String> scopes = methIter.next().getDocScopes();
141 |                         scopes.retainAll(requestedScopes);
142 |                         if (scopes.isEmpty()) {
143 |                             methIter.remove();
144 |                         }
145 |                     }
146 |                     if (resource.getRequestMethodDocs().isEmpty()) {
147 |                         resIter.remove();
148 |                     }
149 |                 }
150 |                 if (api.getResources().isEmpty()) {
151 |                     apiIter.remove();
152 |                 }
153 |             }
154 |         }
155 |         
156 |         return filteredApis;
157 |     }
