159 |     /**
160 |      * derive the common base URI for all resources in each API and declare that the API mount point.
161 |      */
162 |     private void deriveBaseURIs(Collection<RestDocumentation.RestApi> apis) {
163 |         for (RestDocumentation.RestApi api : apis) {
164 |             String basePath = null;
165 |             for (RestDocumentation.RestApi.Resource resource : api.getResources()) {
166 |                 String resourcePath = resource.getPath();
167 |                 if (null != resourcePath) {
168 |                     if (null == basePath) {
169 |                         basePath = resourcePath;
170 |                     } else {
171 |                         String[] baseParts = basePath.split("/");
172 |                         String[] resourceParts = resourcePath.split("/");
173 |                         basePath = "";
174 |                         int smallerLength = Math.min(baseParts.length, resourceParts.length);
175 |                         for (int i = 0; i < smallerLength && baseParts[i].equals(resourceParts[i]); ++i) {
176 |                             if (baseParts[i].length() > 0) {
177 |                                 basePath += "/" + baseParts[i];
178 |                             }
179 |                         }
180 |                     }
181 |                 }
182 |             }
183 |             api.setMount(basePath);
184 |         }
185 |     }
