187 |     List<String> writeDocumentation(List<RestDocumentation> docs, Iterable<Pattern> excludePatterns, String scope)
188 |         throws IOException, ClassNotFoundException, TemplateException {
189 |         List<String> filesWritten = new ArrayList<String>();
190 |         
191 |         // combine APIs from the REST docs into one map, merging those with matching identifiers
192 |         Collection<RestDocumentation.RestApi> apis = mergeApis(docs);
193 | 
194 |         // filter out APIs based on exclude patterns and selected publishing scope
195 |         apis = filterApis(apis, excludePatterns, scope);
196 | 
197 |         // derive the common base URI for all resources of each API and declare that the API mount
198 |         deriveBaseURIs(apis);
199 | 
200 |         Configuration conf = new Configuration();
201 |         conf.setClassForTemplateLoading(RestDocAssembler.class, "");
202 |         conf.setObjectWrapper(new DefaultObjectWrapper());
203 |         Writer out = null;
204 |         try {
205 |             for (RestDocumentation.RestApi api : apis) {
206 |                 Template template = conf.getTemplate(_outputTemplate);
207 |                 Map<String, RestDocumentation.RestApi> root = new HashMap<String, RestDocumentation.RestApi>();
208 |                 root.put("api", api);
209 |                 String fileName = getOutputFileName(api);
210 |                 filesWritten.add(fileName);
211 |                 File file = new File(fileName);
212 |                 out = new FileWriter(file);
213 |                 template.process(root, out);
214 |                 out.flush();
215 |                 System.err.printf("Wrote REST docs to %s\n", file.getAbsolutePath());
216 |             }
217 |         } finally {
218 |             if (out != null) {
219 |                 try {
220 |                     out.close();
221 |                 } catch (IOException ignored) {
222 |                     // ignored
223 |                 }
224 |             }
225 |         }
226 |         return filesWritten;
227 |     }
