229 |     String getOutputFileName(RestDocumentation.RestApi api) {
230 |         String outputFileName = _outputFileName;
231 |         if (!api.getIdentifier().equals(RestDocumentation.RestApi.DEFAULT_IDENTIFIER)) {
232 |             StringBuilder constructedName = new StringBuilder(_outputFileName);
233 |             int identifierIndex = constructedName.lastIndexOf(".");
234 |             if (identifierIndex < 0) {
235 |                 identifierIndex = constructedName.length();
236 |             }
237 |             constructedName.insert(identifierIndex, "-" + api.getIdentifier());
238 |             outputFileName = constructedName.toString();
239 |         }
240 |         return outputFileName;
241 |     }
